type CodeReviewBranch struct {
	Name string `json:"name"`
}

type CodeReviewMaintainer struct {
	ID   int64  `json:"id"`
	Name string `json:"name"`
}

type CodeReviewMergeRequest struct {
	URI string `json:"uri"`
}

type CodeReview struct {
	MergeRequest           CodeReviewMergeRequest `json:"mergeRequest"`
	ReviewedByMaintainers  int                    `json:"reviewedByMaintainers"`
	ApprovedByMaintainers  int                    `json:"approvedByMaintainers"`
	ResetApprovalsOnCommit bool                   `json:"resetApprovalsOnCommit"`
	InvolvedMaintainers    []CodeReviewMaintainer `json:"involvedMaintainers"`
	Branch                 CodeReviewBranch       `json:"branch"`
}

type AttestationInput struct {
	RepositoryURL string
	Output        *string
	Branch        *string
	Tag           *string
	CommitRef     *string
	CommitSHA     *string
}

func getCommit(ctx context.Context, gitClient observe.GitClient, repositoryURL string, commitRef *string, commitSHA *string) (common.Commit, *string, error) {
	var commit common.Commit
	// in case either one is nil we just get the commit from the latest release
	if commitRef == nil || commitSHA == nil {
		release, err := observe.GetLatestReleaseForRepo(ctx, gitClient, repositoryURL)
		if err != nil {
			return nil, nil, errors.Wrap(err, "failed to get latest release")
		}
		commit = release.GetCommit()
		commitRef = common.Ptr(release.GetTagName())
	} else {
		var err error
		commit, err = gitClient.GetCommit(ctx, repositoryURL, *commitSHA, common.GetCommitOptions{})
		if err != nil {
			return nil, nil, errors.Wrap(err, "failed to get commit from CI_COMMIT_SHA")
		}
	}

	return commit, commitRef, nil
}

func getCodeReview(ctx context.Context, gitClient observe.GitClient, repositoryURL string, commit common.Commit) (*CodeReview, error) {
	mergeRequests, err := gitClient.GetMergeRequests(ctx, repositoryURL, common.ListMergeRequestsOptions{
		State: common.Ptr("merged"),
	})
	if err != nil {
		return nil, errors.Wrap(err, "failed to get merge requests")
	}

	members, err := gitClient.GetMemberOfProject(ctx, repositoryURL)
	if err != nil {
		if errors.Is(err, common.ErrForbidden) {
			// A 403 is the normal case for a plain token, so omit the code
			// review claims instead of failing or fabricating them.
			slog.Warn("no permission to list project members, omitting code review details", "err", err) // #nosec G706 // False Positive: https://github.com/securego/gosec/issues/1622
			return nil, nil
		}

		return nil, errors.Wrap(err, "failed to get project members")
	}

